def parse_time(t):
    # t like '1:32' or '12:34' or '1:02:03'
    parts=t.strip().split(':')
    parts=[int(p) for p in parts]
    if len(parts)==2:
        return parts[0]*60+parts[1]
    elif len(parts)==3:
        return parts[0]*3600+parts[1]*60+parts[2]
    else:
        raise ValueError('bad time '+t)

